"""Generated by solo-to-scale; edit `templates/tools/autopilot.py` in the plugin, then run upgrade.

Autopilot: the AI team finds its own work and starts each other, inside the founder's budgets and gates.

  python tools/autopilot.py gaps              # what the current stage and the goals need that no open ticket covers
  python tools/autopilot.py plan [--dry-run]  # open one planning ticket for the chief of staff when there are gaps
  python tools/autopilot.py due [--github-output FILE]
                                              # CI: plan, then which roles should run now, as a job matrix
  python tools/autopilot.py finish <role>     # CI, after a run: if it left its run lock, record it as failed

How the team works on its own:
1. Planning. `plan` compares the playbook's current stage (its gate), the live initiatives in founder/goals.json,
   key results with no initiative, and what the goal tree needs next (goals.py `due`) with the open tickets. A
   gap is covered by an open ticket labelled `stage:<n>` or `initiative:<id>`. When something isn't covered, it
   opens one ticket for `role:chief-of-staff` (label `autopilot-plan`) listing the gaps; the chief of staff turns
   it into tickets for the right roles (`coordinate` skill), so the founder never has to hand out tasks.
2. Waking. `due` lists every role that has work right now: its own claimed ticket to resume, or a ready one
   (unclaimed, unblocked, claimable under the plan gate). The `agents` workflow runs it on every ticket event
   and every three hours, and starts one Claude Code run per role (the `heartbeat` skill). A handoff or a newly
   unblocked ticket therefore starts the next role straight away.
3. Limits. Only roles whose heartbeat is on, with a budget that isn't spent, not paused, and with no run
   active. `autopilot.max_runs_per_day` caps all runs together; founder gates are untouched.

Policy: `autopilot` in founder/heartbeats.json (founder-owned; the `budget` gate). Missing means off:
  {"enabled": false, "plan_every_hours": 24, "max_runs_per_day": 12, "max_parallel": 2,
   "models": {"architect": "opus"}}
Python 3 standard library plus the gh CLI.
"""
from __future__ import annotations

import argparse
import datetime as dt
import json
import os
import subprocess
import sys
from pathlib import Path
from typing import Any

sys.path.insert(0, str(Path(__file__).resolve().parent))
import _s2s as s  # noqa: E402
import approval  # noqa: E402
import control  # noqa: E402
import goals  # noqa: E402
import heartbeat  # noqa: E402
import tickets  # noqa: E402

OK, ERROR = 0, 5
PLAN_LABEL, STAGE_PREFIX, GOAL_TREE = "autopilot-plan", "stage:", "goal-tree"
DEFAULTS = {"enabled": False, "plan_every_hours": 24, "max_runs_per_day": 12, "max_parallel": 2}
# The model each role runs on (roles/*.yaml `tier`): strongest for architecture, mid-tier for the rest.
MODELS = {"architect": "opus"}
DEFAULT_MODEL = "sonnet"
IDLE_HOURS = 1  # a role whose last run found nothing to do waits this long
COOLDOWN_HOURS = 6  # a ticket whose last run ended blocked or failed waits this long before a retry
BUILD_STAGES = range(13, 18)
TOKEN_ENV = "S2S_HAS_AGENT_TOKEN"


def settings(pol: dict[str, Any]) -> dict[str, Any]:
    got = pol.get("autopilot") if isinstance(pol.get("autopilot"), dict) else {}
    out = {**DEFAULTS, **got}
    for k in ("plan_every_hours", "max_runs_per_day", "max_parallel"):
        v = out.get(k)
        out[k] = v if isinstance(v, (int, float)) and not isinstance(v, bool) and v > 0 else DEFAULTS[k]
    out["enabled"] = out.get("enabled") is True
    return out


def model_of(cfg: dict[str, Any], role: str) -> str:
    v = str((cfg.get("models") or {}).get(role) or MODELS.get(role) or DEFAULT_MODEL)
    return v if v.replace("-", "").replace(".", "").isalnum() and len(v) <= 40 else DEFAULT_MODEL


# --- gaps (pure, given the repo and the open tickets) -----------------------------------------------------

def covered(open_tickets: list[dict[str, Any]]) -> set[str]:
    return {lb for t in open_tickets for lb in tickets.labels_of(t)}


def gaps(root: Path, open_tickets: list[dict[str, Any]], today: dt.date) -> list[dict[str, str]]:
    """What the team should be working on and isn't: each with a key (the label that covers it) and a line."""
    have = covered(open_tickets)
    out: list[dict[str, str]] = []
    for st in s.playbook(root):
        if str(st.get("status", "")).strip().lower() != "current":
            continue
        key = f"{STAGE_PREFIX}{st['stage']}"
        if key not in have:
            out.append({"key": key, "what": f"Stage {st['stage']} {st.get('name', '')}: pass its gate, "
                                            f"\"{st.get('gate', '')}\""})
    data = goals.load(root)
    if "_error" not in data:
        for i in goals.live_initiatives(data):
            key = goals.initiative_label(str(i.get("id")))
            if key not in have:
                out.append({"key": key, "what": f"Initiative {i.get('id')} {i.get('title', '')} (key result "
                                                f"{i.get('key_result', '?')}, owner {i.get('owner') or 'not set'})"})
        with_init = {str(i.get("key_result")) for i in goals.initiatives(data)}
        for o in goals.active(data):
            for kr in o.get("key_results") or []:
                if isinstance(kr, dict) and str(kr.get("id")) not in with_init and f"kr:{kr.get('id')}" not in have:
                    out.append({"key": f"kr:{kr.get('id')}", "what": f"Key result {kr.get('id')} "
                                f"{kr.get('metric', '')} has no initiative: propose one in founder/goals.json (okr-plan)"})
        need = goals.due(root, data, today)
        if need and GOAL_TREE not in have:
            out.append({"key": GOAL_TREE, "what": f"Goal tree: {need}"})
    return out


def next_slice(root: Path) -> str:
    """The first slice that isn't done, during the build stages: a hint for the planner."""
    stages = {x["stage"]: str(x.get("status", "")).lower() for x in s.playbook(root)}
    if not any(stages.get(n) == "current" for n in BUILD_STAGES):
        return ""
    for sl in s.slices(root, s.config(root))["slices"]:
        if isinstance(sl, dict) and str(sl.get("status", "")).lower() != "done":
            return f"{sl.get('id', '?')} {sl.get('name') or sl.get('title') or ''}".strip()
    return ""


def plan_body(found: list[dict[str, str]], hint: str) -> str:
    return "\n".join([
        "**Role:** `role:chief-of-staff`", "**Opened by:** the autopilot (`tools/autopilot.py plan`)",
        "**Parent:** none", "**Blocked by:** nothing", "",
        "## Goal",
        "> Turn every gap below into work for the right roles, so the team moves toward the objectives without"
        " waiting to be told.", "",
        "## Gaps (nothing open covers these)", *[f"- `{g['key']}`: {g['what']}" for g in found],
        *([f"- next slice to build: {hint}"] if hint else []), "",
        "## How",
        "1. Read AGENTS.md, HANDOFF.md, `python tools/goals.py show` and `python tools/tickets.py queue chief-of-staff`.",
        "2. Each gap's key (in backticks) is the label that covers it. Where an open ticket already does the work,"
        " add that label to it instead of opening another.",
        "3. Otherwise open one ticket per role and outcome with `python tools/tickets.py new <role> ... --stage <n>`"
        " or `--initiative <id>`, ordered with `--blocked-by`, with this ticket as `--parent`; for any other gap,"
        " add its key as a label to the ticket that covers it.",
        "4. With the plan gate on (founder/gates.json), run `python tools/tickets.py plan <this ticket> --by"
        " chief-of-staff --note \"<why>\"` before finishing: no sub-ticket can start until the founder approves it.",
        "5. Anything only the founder can do (a decision, a secret, money, a go-live) goes through the `gate` skill"
        " or `tickets.py escalate`: it shows in Needs you.",
        "6. `tickets.py done` this ticket once every gap has a ticket.", "",
        "## Done when", "> Every gap above is covered by an open ticket, or escalated to the founder.", "",
        "A ticket never approves anything; founder gates still apply."])


# --- GitHub ----------------------------------------------------------------------------------------------

def hours_since_last_plan(hub: tickets.Hub, now: dt.datetime) -> float | None:
    last = None
    for t in hub.tickets("all", PLAN_LABEL):
        d = t.get("closed_at") or t.get("created_at") or ""
        try:
            when = dt.datetime.fromisoformat(str(d).replace("Z", "+00:00"))
        except ValueError:
            continue
        last = when if last is None or when > last else last
    return (now - last).total_seconds() / 3600 if last else None


def plan(hub: tickets.Hub, root: Path, cfg: dict[str, Any], now: dt.datetime, dry_run: bool = False,
         open_tickets: list[dict[str, Any]] | None = None) -> dict[str, Any] | None:
    """Open the planning ticket when there are gaps, none is open, and the last one is old enough."""
    open_tickets = hub.tickets("open") if open_tickets is None else open_tickets
    if any(PLAN_LABEL in tickets.labels_of(t) for t in open_tickets):
        print("planning: a planning ticket is already open")
        return None
    found = gaps(root, open_tickets, now.date())
    if not found:
        print("planning: nothing uncovered; every current stage and live initiative has an open ticket")
        return None
    age = hours_since_last_plan(hub, now)
    if age is not None and age < cfg["plan_every_hours"]:
        print(f"planning: {len(found)} gaps, but the last plan was {age:.0f} h ago (every {cfg['plan_every_hours']} h)")
        return None
    body = plan_body(found, next_slice(root))
    if dry_run:
        print(f"would open a planning ticket for role:chief-of-staff:\n\n{body}")
        return None
    made = hub.api("issues", "-X", "POST", payload={
        "title": f"Plan the next work: {len(found)} gap{'s' if len(found) != 1 else ''} toward the goals",
        "body": body, "labels": [tickets.TICKET, "role:chief-of-staff", PLAN_LABEL]})
    hub.record(made["number"], "chief-of-staff", "opened", f"autopilot: {len(found)} gaps need tickets", to="chief-of-staff")
    print(f"planning: opened #{made['number']} for role:chief-of-staff")
    return made


def stalled(runs: list[dict[str, Any]], role: str, now: dt.datetime) -> set[int]:
    """Tickets this role's last run on them ended blocked or failed within COOLDOWN_HOURS: don't retry them yet."""
    last: dict[int, dict[str, Any]] = {}
    for e in runs:
        if e.get("role") == role and isinstance(e.get("ticket"), int):
            last[e["ticket"]] = e
    out = set()
    for n, e in last.items():
        try:
            at = dt.datetime.fromisoformat(str(e.get("at")).replace("Z", "+00:00"))
        except ValueError:
            continue
        if e.get("outcome") in ("blocked", "failed") and (now - at).total_seconds() < COOLDOWN_HOURS * 3600:
            out.add(n)
    return out


def idle_recently(runs: list[dict[str, Any]], role: str, now: dt.datetime) -> bool:
    """This role's latest run did nothing (no ticket) less than IDLE_HOURS ago."""
    mine = [e for e in runs if e.get("role") == role]
    if not mine or mine[-1].get("outcome") != "no-work" or mine[-1].get("ticket") is not None:
        return False
    try:
        at = dt.datetime.fromisoformat(str(mine[-1].get("at")).replace("Z", "+00:00"))
    except ValueError:
        return False
    return (now - at).total_seconds() < IDLE_HOURS * 3600


def has_work(hub: tickets.Hub, role: str, open_tickets: list[dict[str, Any]], skip: set[int] | None = None) -> str:
    """Why this role should run now, or empty. Escalated tickets wait for whoever they went to; `skip` holds the
    tickets that just stalled, so a ticket blocked on the founder isn't retried run after run."""
    skip = skip or set()
    mine = [t for t in open_tickets if tickets.role_of(t) == role]
    for t in mine:
        if tickets.CLAIMED in tickets.labels_of(t) and hub.holder(t["number"]) == f"role:{role}":
            return f"resume #{t['number']}"
    for t in mine:
        labels = tickets.labels_of(t)
        if tickets.CLAIMED in labels or tickets.BLOCKED in labels or t["number"] in skip:
            continue
        if any(x.startswith(tickets.ESCALATED) for x in labels):
            continue
        if not tickets.plan_refusal(hub, t):
            return f"ready #{t['number']}"
    return ""


def ask_for_plans(hub: tickets.Hub, open_tickets: list[dict[str, Any]]) -> list[str]:
    """Sub-tickets waiting on a plan nobody asked the founder for: ask once per parent, as the chief of staff."""
    if not tickets.plan_gate_on(tickets.hub_root(hub)):
        return []
    asked, out = set(), []
    for t in open_tickets:
        parents = tickets.links(t.get("body", ""))["parent"]
        if not parents or parents[0] in asked or tickets.latest_plan(hub, parents[0]) is not None:
            continue
        asked.add(parents[0])
        note = "Opened by the autopilot: these sub-tickets can't start until you approve the plan."
        if tickets.cmd_plan(argparse.Namespace(n=parents[0], by="chief-of-staff", note=note), hub) == tickets.OK:
            out.append(f"plan: asked the founder to approve #{parents[0]}'s plan")
    return out


def month_runs(hub: tickets.Hub, now: dt.datetime) -> list[dict[str, Any]]:
    month = now.strftime("%Y-%m")
    return heartbeat.entries(heartbeat.Costs(hub, month).comments(), month)


def runs_today(hub: tickets.Hub, now: dt.datetime, runs: list[dict[str, Any]] | None = None) -> int:
    """Every run today counts toward the cap, even one that found nothing to do (`finish` records those)."""
    day = now.strftime("%Y-%m-%d")
    return sum(1 for e in (month_runs(hub, now) if runs is None else runs) if str(e.get("at", "")).startswith(day))


def due(hub: tickets.Hub, root: Path, pol: dict[str, Any], now: dt.datetime) -> tuple[list[dict[str, str]], list[str]]:
    """(the roles to start now, one line per role saying why or why not)."""
    cfg = settings(pol)
    if not cfg["enabled"]:
        return [], ["autopilot is off: set \"autopilot\": {\"enabled\": true} in founder/heartbeats.json"]
    open_tickets = hub.tickets("open")
    made = plan(hub, root, cfg, now, open_tickets=open_tickets)
    if made:
        open_tickets = hub.tickets("open")
    asked = ask_for_plans(hub, open_tickets)
    runs = month_runs(hub, now)
    left = int(cfg["max_runs_per_day"]) - runs_today(hub, now, runs)
    if left <= 0:
        return [], [f"stop: {cfg['max_runs_per_day']} runs today already (autopilot.max_runs_per_day)"]
    month = now.strftime("%Y-%m")
    totals = heartbeat.Costs(hub, month).totals()
    ccap, cused, _ = heartbeat.standing(hub, root, pol, heartbeat.COMPANY, month, totals)
    if ccap is not None and cused >= ccap:
        return [], [f"stop: the company AI budget is spent (${cused:.2f} of ${ccap:.2f})"]
    ctl = control.read(hub, root)
    out, why = [], list(asked)
    for role in tickets.ROLES:
        rcfg = (pol.get("roles") or {}).get(role) or {}
        cap, used, _ = heartbeat.standing(hub, root, pol, role, month, totals)
        held = heartbeat.run_holder(hub, role)
        reason = ("heartbeat off" if not rcfg.get("enabled") else
                  f"paused ({control.paused(ctl, role)})" if control.paused(ctl, role) else
                  "no budget set" if cap is None else
                  f"budget spent (${used:.2f} of ${cap:.2f})" if used >= cap else
                  "a run is active" if held and now.timestamp() - held[1] < heartbeat.STALE_HOURS * 3600 else "")
        if not reason and idle_recently(runs, role, now):
            reason = f"its last run found nothing to do (waits {IDLE_HOURS}h)"
        work = "" if reason else has_work(hub, role, open_tickets, stalled(runs, role, now))
        if not reason and not work:
            reason = "nothing ready"
        if work and len(out) < left:
            out.append({"role": role, "model": model_of(cfg, role), "prompt": heartbeat.task_prompt(role)})
            why.append(f"{role}: start ({work})")
        else:
            why.append(f"{role}: {reason or 'over today’s run cap'}")
    return out, why


def cmd_gaps(a: argparse.Namespace, hub: tickets.Hub, pol: dict[str, Any]) -> int:
    found = gaps(a.root, hub.tickets("open"), dt.datetime.now(dt.timezone.utc).date())
    for g in found:
        print(f"- {g['key']}: {g['what']}")
    hint = next_slice(a.root)
    if hint:
        print(f"next slice: {hint}")
    print(f"{len(found)} gaps" if found else "No gaps: every current stage and live initiative has an open ticket.")
    return OK


def cmd_plan(a: argparse.Namespace, hub: tickets.Hub, pol: dict[str, Any]) -> int:
    cfg = {**settings(pol), "plan_every_hours": 0.0} if a.force else settings(pol)
    plan(hub, a.root, cfg, dt.datetime.now(dt.timezone.utc), dry_run=a.dry_run)
    return OK


def cmd_due(a: argparse.Namespace, hub: tickets.Hub, pol: dict[str, Any]) -> int:
    now = dt.datetime.fromtimestamp(a.now, dt.timezone.utc) if a.now else dt.datetime.now(dt.timezone.utc)
    roles, why = due(hub, a.root, pol, now)
    for line in why:
        print(line)
    token = os.environ.get(TOKEN_ENV, "").lower() == "true"
    if roles and not token and a.github_output:
        print("no CLAUDE_CODE_OAUTH_TOKEN or ANTHROPIC_API_KEY secret: nothing starts here; the roles' cloud"
              " scheduled tasks pick this work up on their schedule")
        roles = []
    if a.github_output:
        with open(a.github_output, "a", encoding="utf-8") as f:
            f.write(f"run={'yes' if roles else 'no'}\nmatrix={json.dumps(roles)}\n"
                    f"parallel={int(settings(pol)['max_parallel'])}\n")
    else:
        print(json.dumps(roles, indent=1))
    return OK


def cmd_finish(a: argparse.Namespace, hub: tickets.Hub, pol: dict[str, Any]) -> int:
    """After a CI run: a run that ended without `heartbeat.py end` (crash, timeout) is recorded as failed."""
    tickets.need_role(a.role)
    if heartbeat.run_holder(hub, a.role) is None:
        link = heartbeat.session_link(a.session)
        now = dt.datetime.now(dt.timezone.utc)
        if link and not any(e.get("session") == link for e in month_runs(hub, now)):
            # The run never started a heartbeat: record it, so it counts toward the daily cap.
            return heartbeat.main(["end", a.role, "--usd", "0", "--outcome", "no-work", "--root", str(a.root),
                                   "--note", "the run ended without starting a heartbeat", "--session", a.session])
        print(f"role:{a.role}'s run ended cleanly")
        return OK
    claimed = [t["number"] for t in hub.tickets("open") if tickets.role_of(t) == a.role
               and hub.holder(t["number"]) == f"role:{a.role}"]
    return heartbeat.main(["end", a.role, "--outcome", "failed", "--root", str(a.root),
                           "--note", "the run stopped before ending itself (timeout or error)",
                           *(["--ticket", str(claimed[0])] if claimed else []),
                           *(["--session", a.session] if a.session else [])])


def main(argv: list[str] | None = None) -> int:
    common = argparse.ArgumentParser(add_help=False)
    common.add_argument("--root", type=Path, default=s.ROOT, help=argparse.SUPPRESS)
    ap = argparse.ArgumentParser(description="Autopilot: agents that find their own work")
    sub = ap.add_subparsers(dest="cmd", required=True)
    sub.add_parser("gaps", parents=[common])
    p = sub.add_parser("plan", parents=[common])
    p.add_argument("--dry-run", action="store_true")
    p.add_argument("--force", action="store_true", help="ignore plan_every_hours")
    p = sub.add_parser("due", parents=[common])
    p.add_argument("--github-output", default="")
    p.add_argument("--now", type=float, default=0, help=argparse.SUPPRESS)
    p = sub.add_parser("finish", parents=[common])
    p.add_argument("role")
    p.add_argument("--session", default="")
    a = ap.parse_args(argv)
    pol = heartbeat.policy(a.root)
    repo = approval.repo_name(a.root)
    if not repo:
        print("can't tell which GitHub repo this is: nothing done")
        return ERROR
    run = {"gaps": cmd_gaps, "plan": cmd_plan, "due": cmd_due, "finish": cmd_finish}[a.cmd]
    try:
        hub = tickets.Hub(repo)
        hub.root = a.root
        return run(a, hub, pol)
    except (subprocess.CalledProcessError, FileNotFoundError, ValueError, KeyError, TypeError) as exc:
        print(f"GitHub unavailable or unexpected reply ({type(exc).__name__}): nothing more is done")
        if getattr(a, "github_output", ""):
            with open(a.github_output, "a", encoding="utf-8") as f:
                f.write("run=no\nmatrix=[]\nparallel=1\n")
        return ERROR


if __name__ == "__main__":
    sys.exit(main())
